-- EasyStore sample data for PostgreSQL (NOT an Odoo dump). Run: psql -d yourdb -f database_backup.sql
BEGIN;
CREATE TABLE IF NOT EXISTS easy_categories(id serial PRIMARY KEY,slug text UNIQUE NOT NULL,name_en text NOT NULL,name_ur text,image text);
CREATE TABLE IF NOT EXISTS easy_products(id integer PRIMARY KEY,slug text UNIQUE NOT NULL,name_en text NOT NULL,name_ur text,category_slug text REFERENCES easy_categories(slug),price numeric(12,2) NOT NULL,old_price numeric(12,2),stock integer DEFAULT 0,rating numeric(2,1),brand text,description_en text,description_ur text);
CREATE TABLE IF NOT EXISTS easy_product_images(id serial PRIMARY KEY,product_id integer REFERENCES easy_products(id) ON DELETE CASCADE,position smallint NOT NULL CHECK(position BETWEEN 1 AND 8),file text NOT NULL);
CREATE TABLE IF NOT EXISTS easy_orders(order_id text PRIMARY KEY,order_date date,customer text,phone text,city text,payment text,status text,total numeric(12,2));
CREATE TABLE IF NOT EXISTS easy_order_lines(id serial PRIMARY KEY,order_id text REFERENCES easy_orders(order_id) ON DELETE CASCADE,product_id integer REFERENCES easy_products(id),qty integer NOT NULL,unit_price numeric(12,2) NOT NULL);
COMMIT;
